        --muted: #9fb0cc;
        --accent: #7c9cff;
        --accent-strong: #9cb2ff;
        --error: #ff7b7b;
        --field-bg: #0d1526;
        --shadow: 0 24px 80px rgba(0, 0, 0, 0.35);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 156, 255, 0.18), transparent 35%),
          linear-gradient(180deg, #08101d 0%, #0b1220 100%);
        color: var(--text);
      }

      .page {
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 16px;
      }

      .card {
        width: min(100%, 620px);
        background: rgba(17, 26, 46, 0.88);
        border: 1px solid rgba(38, 50, 77, 0.9);
        border-radius: 24px;
        box-shadow: var(--shadow);
        padding: 32px;
        backdrop-filter: blur(14px);
      }

      .eyebrow {
        margin: 0 0 10px;
        color: var(--accent-strong);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0 0 12px;
        font-size: clamp(1.8rem, 4vw, 2.6rem);
        line-height: 1.1;
      }

      .lede {
        margin: 0 0 28px;
        color: var(--muted);
        line-height: 1.6;
      }

      .form-grid {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-size: 0.95rem;
        font-weight: 600;
      }

      input {
        width: 100%;
        border: 1px solid var(--panel-border);
        border-radius: 14px;
        background: var(--field-bg);
        color: var(--text);
        padding: 14px 16px;
        font: inherit;
        outline: none;
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      input::placeholder {
        color: #7484a4;
      }

      input:focus {
        border-color: rgba(124, 156, 255, 0.95);
        box-shadow: 0 0 0 4px rgba(124, 156, 255, 0.18);
      }

      .field-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.9rem;
        line-height: 1.45;
      }

      .field-error {
        min-height: 1.1em;
        margin: 0;
        color: var(--error);
        font-size: 0.9rem;
        line-height: 1.45;
      }

      button {
        margin-top: 6px;
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        background: linear-gradient(135deg, var(--accent), #5f7dff);
        color: white;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 30px rgba(95, 125, 255, 0.25);
        transition: transform 0.2s ease, box-shadow 0.2s ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 16px 34px rgba(95, 125, 255, 0.3);
      }

      button:active {
        transform: translateY(0);
      }

      .success {
        margin-top: 18px;
        color: #9be7b4;
        font-size: 0.95rem;
        min-height: 1.2em;
      }

      @media (max-width: 520px) {
        .card {
          padding: 24px;
          border-radius: 20px;
        }
      }
