                onBlur: () => touch("fullName")
              }),
              e(Field, {
                id: "email",
                label: "Email address",
                type: "email",
                value: values.email,
                placeholder: "jane@example.com",
                required: true,
                autoComplete: "email",
                error: errors.email,
                onChange: (event) => setValue("email", event.target.value),
                onBlur: () => touch("email")
              }),
              e(Field, {
