                inputMode: "tel",
                note: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
                error: "",
                onChange: (event) => setValue("phone", event.target.value),
                onBlur: () => touch("phone")
              }),
              e("button", { type: "submit" }, "Submit"),
              e("div", { className: "success", role: "status", "aria-live": "polite" }, success)
            )
          )
        );
      }

      ReactDOM.createRoot(document.getElementById("root")).render(e(SupportContactForm));
