      }

      .lede {
        margin: 0 0 28px;
        color: var(--muted);
        line-height: 1.6;
      }

      .form-grid {
        display: grid;
        gap: 18px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-size: 0.95rem;
        font-weight: 600;
      }

      input {
        width: 100%;
        border: 1px solid var(--panel-border);
