        margin: 0;
        color: var(--muted);
        font-size: 0.9rem;
        line-height: 1.45;
      }

      .field-error {
        min-height: 1.1em;
        margin: 0;
        color: var(--error);
        font-size: 0.9rem;
        line-height: 1.45;
      }

      button {
        margin-top: 6px;
        border: 0;
        border-radius: 14px;
        padding: 14px 18px;
        background: linear-gradient(135deg, var(--accent), #5f7dff);
        color: white;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 12px 30px rgba(95, 125, 255, 0.25);
