     <script>
       const e = React.createElement;
       const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

       function useFormState() {
         const [state, setState] = React.useState({
           values: { fullName: "", email: "", phone: "" },
           touched: { fullName: false, email: false, phone: false },
           submitted: false,
           success: ""
         });

         const isValidEmail = (email) => EMAIL_RE.test(email.trim());
         const isFormValid = (values) => values.fullName.trim() && isValidEmail(values.email);

         const setValue = (name, value) => {
           setState((current) => ({
             ...current,
             values: { ...current.values, [name]: value },
             success: ""
           }));
         };

         const touch = (name) => {
           setState((current) => ({
             ...current,
             touched: { ...current.touched, [name]: true }
           }));
         };

         const submit = (event) => {
           event.preventDefault();
           setState((current) => ({
             ...current,
             submitted: true,
             success: isFormValid(current.values) ? "Thanks — your message is ready to send." : ""
           }));
         };

         return { state, setValue, touch, submit };
       }

       function Field({ id, label, type, value, placeholder, note, error, required, onChange, onBlur, autoComplete, inputMode }) {
         return e(
           "div",
           { className: "form-field" },
           e("label", { htmlFor: id }, [label, required ? " *" : ""]),
           e("input", {
             id,
             name: id,
             type,
             value,
             placeholder,
             required,
             autoComplete,
             inputMode,
             onChange,
             onBlur
           }),
           note ? e("p", { className: "field-note", id: `${id}-note` }, note) : null,
           e("p", { className: "field-error", id: `${id}-error`, "aria-live": "polite" }, error || "\u00a0")
         );
       }

       function SupportContactForm() {
         const { state, setValue, touch, submit } = useFormState();
         const { values, touched, submitted, success } = state;

         const errors = {
           fullName:
             (submitted || touched.fullName) && !values.fullName.trim() ? "Full name is required." : "",
           email:
             (submitted || touched.email) && !values.email.trim()
               ? "Email address is required."
               : (submitted || touched.email) && values.email && !EMAIL_RE.test(values.email.trim())
                 ? "Enter a valid email address."
                 : ""
         };

         return e(
